#!/usr/bin/env node

/**
 * CSP Headers Test Script
 *
 * This script tests the Content Security Policy implementation by:
 * 1. Starting the backend server
 * 2. Making HTTP requests to verify CSP headers
 * 3. Validating all security headers are present
 * 4. Checking development vs production policies
 */

import http from 'http';

const SERVER_PORT = 3000;
const SERVER_HOST = 'localhost';

/**
 * Make HTTP request and return headers
 */
function fetchHeaders(path = '/health') {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: SERVER_HOST,
      port: SERVER_PORT,
      path: path,
      method: 'GET',
    };

    const req = http.request(options, (res) => {
      resolve({
        statusCode: res.statusCode,
        headers: res.headers
      });
    });

    req.on('error', reject);
    req.setTimeout(5000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.end();
  });
}

/**
 * Wait for server to be ready
 */
async function waitForServer(maxAttempts = 10) {
  for (let i = 0; i < maxAttempts; i++) {
    try {
      await fetchHeaders('/health');
      return true;
    } catch (err) {
      if (i === maxAttempts - 1) throw err;
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }
  return false;
}

/**
 * Validate CSP header
 */
function validateCSP(cspHeader, environment = 'development') {
  const results = {
    passed: [],
    failed: [],
    warnings: []
  };

  if (!cspHeader) {
    results.failed.push('CSP header is missing');
    return results;
  }

  console.log(`\n📋 CSP Policy (${environment}):`);
  console.log(`   ${cspHeader}\n`);

  // Required directives for both environments
  const requiredDirectives = [
    "default-src 'self'",
    'script-src',
    'style-src',
    'img-src',
    'font-src',
    'connect-src',
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "object-src 'none'"
  ];

  requiredDirectives.forEach(directive => {
    if (cspHeader.includes(directive.split(' ')[0])) {
      results.passed.push(`✅ Contains ${directive.split(' ')[0]}`);
    } else {
      results.failed.push(`❌ Missing ${directive.split(' ')[0]}`);
    }
  });

  // Environment-specific checks
  if (environment === 'development') {
    if (cspHeader.includes("'unsafe-inline'") && cspHeader.includes("'unsafe-eval'")) {
      results.passed.push("✅ Development policy includes unsafe-inline and unsafe-eval (for Vite HMR)");
    } else {
      results.warnings.push("⚠️  Development policy should include unsafe-inline and unsafe-eval for Vite HMR");
    }

    if (cspHeader.includes('localhost:5173') || cspHeader.includes('ws://localhost:5173')) {
      results.passed.push("✅ Development policy includes localhost:5173");
    } else {
      results.warnings.push("⚠️  Development policy should include localhost:5173 for HMR");
    }
  }

  if (environment === 'production') {
    if (!cspHeader.includes("'unsafe-eval'")) {
      results.passed.push("✅ Production policy does NOT include unsafe-eval (secure)");
    } else {
      results.failed.push("❌ Production policy should NOT include unsafe-eval");
    }

    if (cspHeader.includes('upgrade-insecure-requests')) {
      results.passed.push("✅ Production policy includes upgrade-insecure-requests");
    } else {
      results.warnings.push("⚠️  Production policy should include upgrade-insecure-requests");
    }
  }

  // Check for AI service domains
  const aiDomains = [
    'openrouter.ai',
    'api.replicate.com',
    'generativelanguage.googleapis.com',
    'api.openai.com'
  ];

  aiDomains.forEach(domain => {
    if (cspHeader.includes(domain)) {
      results.passed.push(`✅ Allows ${domain}`);
    }
  });

  // Check for Google Fonts
  if (cspHeader.includes('fonts.googleapis.com') && cspHeader.includes('fonts.gstatic.com')) {
    results.passed.push("✅ Google Fonts allowlisted");
  }

  // Check for blob/data URLs
  if (cspHeader.includes('blob:') && cspHeader.includes('data:')) {
    results.passed.push("✅ blob: and data: URLs allowed for images");
  }

  return results;
}

/**
 * Main test function
 */
async function runTests() {
  console.log('🧪 CSP Headers Test Suite\n');
  console.log('=' .repeat(70));

  try {
    console.log('\n⏳ Waiting for server to be ready...');
    await waitForServer();
    console.log('✅ Server is ready\n');

    // Test 1: Health endpoint
    console.log('📍 Test 1: Health Endpoint Headers');
    console.log('-'.repeat(70));
    const healthResponse = await fetchHeaders('/health');

    console.log(`\nStatus Code: ${healthResponse.statusCode}`);
    console.log('\nSecurity Headers:');

    const securityHeaders = [
      'content-security-policy',
      'content-security-policy-report-only',
      'x-frame-options',
      'x-content-type-options',
      'x-xss-protection',
      'referrer-policy',
      'permissions-policy'
    ];

    let headersFound = 0;
    securityHeaders.forEach(header => {
      if (healthResponse.headers[header]) {
        headersFound++;
        console.log(`✅ ${header}: ${healthResponse.headers[header].substring(0, 80)}${healthResponse.headers[header].length > 80 ? '...' : ''}`);
      } else {
        console.log(`❌ ${header}: NOT FOUND`);
      }
    });

    // Validate CSP
    const cspHeader = healthResponse.headers['content-security-policy'] ||
                      healthResponse.headers['content-security-policy-report-only'];

    const environment = process.env.NODE_ENV || 'development';
    const validation = validateCSP(cspHeader, environment);

    console.log('\n📊 CSP Validation Results:');
    console.log('-'.repeat(70));

    if (validation.passed.length > 0) {
      console.log('\n✅ Passed Checks:');
      validation.passed.forEach(msg => console.log(`   ${msg}`));
    }

    if (validation.warnings.length > 0) {
      console.log('\n⚠️  Warnings:');
      validation.warnings.forEach(msg => console.log(`   ${msg}`));
    }

    if (validation.failed.length > 0) {
      console.log('\n❌ Failed Checks:');
      validation.failed.forEach(msg => console.log(`   ${msg}`));
    }

    // Test 2: Additional headers verification
    console.log('\n\n📍 Test 2: Additional Security Headers');
    console.log('-'.repeat(70));

    const expectedHeaders = {
      'x-frame-options': 'DENY',
      'x-content-type-options': 'nosniff',
      'x-xss-protection': '1; mode=block',
      'referrer-policy': 'strict-origin-when-cross-origin'
    };

    let additionalHeadersPassed = 0;
    Object.entries(expectedHeaders).forEach(([header, expectedValue]) => {
      const actualValue = healthResponse.headers[header];
      if (actualValue === expectedValue) {
        console.log(`✅ ${header}: ${actualValue}`);
        additionalHeadersPassed++;
      } else {
        console.log(`❌ ${header}: Expected "${expectedValue}", got "${actualValue || 'NOT FOUND'}"`);
      }
    });

    // Summary
    console.log('\n\n' + '='.repeat(70));
    console.log('📊 TEST SUMMARY');
    console.log('='.repeat(70));
    console.log(`✅ Security Headers Found: ${headersFound}/${securityHeaders.length}`);
    console.log(`✅ CSP Checks Passed: ${validation.passed.length}`);
    console.log(`⚠️  CSP Warnings: ${validation.warnings.length}`);
    console.log(`❌ CSP Checks Failed: ${validation.failed.length}`);
    console.log(`✅ Additional Headers Correct: ${additionalHeadersPassed}/${Object.keys(expectedHeaders).length}`);

    const allPassed = validation.failed.length === 0 &&
                      headersFound >= 5 &&
                      additionalHeadersPassed >= 3;

    console.log('\n' + '='.repeat(70));
    if (allPassed) {
      console.log('✅ ALL TESTS PASSED! CSP implementation is working correctly.');
    } else {
      console.log('⚠️  SOME TESTS FAILED. Please review the results above.');
    }
    console.log('='.repeat(70) + '\n');

    return allPassed;

  } catch (error) {
    console.error('\n❌ Error running tests:', error.message);
    console.error('\n💡 Make sure the server is running with: cd server && npm run dev\n');
    return false;
  }
}

// Run tests if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  runTests().then(success => {
    process.exit(success ? 0 : 1);
  });
}

export { runTests, validateCSP };
